import{_ as t,o as i,c as n,a3 as o}from"./chunks/framework.CRbjHCyB.js";const f=JSON.parse('{"title":"Index","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Index | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/"}]]},"headers":[],"relativePath":"clice/cli/index.md","filePath":"en/clice/cli/index.md","lastUpdated":1790004299000}'),a={name:"clice/cli/index.md"};function s(r,e,d,l,c,h){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>clice index</code> builds the persistent symbol index of a workspace ahead of time, so an editor session starts warm instead of indexing in the background while you work. It runs the same indexing pipeline as the server with a worker pool, and the two share one index per build configuration under <code>cache_dir</code>.</p><p><strong>Usage</strong>: <code>clice index [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--workers &lt;n&gt;]</code></p><p>One process writes the index of a workspace at a time. While an editor session has the workspace open, its server holds that role, so <code>clice index</code> asks the server to run the sweep and waits for the result instead of starting a worker pool of its own; the summary says so. A lock held by a process that cannot be asked (another <code>clice index</code>, a server of a different clice build, or one whose configuration keeps background indexing off) makes the command fail with the holder named — rerun it when that process is done.</p><p>The run is resumable: interrupting it with Ctrl-C saves the progress made so far, and the next invocation continues where it left off. Progress is also saved every five minutes, so a crash loses at most that much work. While it runs, a progress line goes to stderr every ten seconds whatever the log level; the final summary on stdout counts the indexed units, the file shards and symbols produced, lists every unit that failed to index, and names the session log directory. The exit code is 0 for a complete index, 1 when some units failed or part of the index could not be persisted, and 130 when interrupted.</p><h2 id="inspecting-the-index" tabindex="-1">Inspecting the index <a class="header-anchor" href="#inspecting-the-index" aria-label="Permalink to &quot;Inspecting the index&quot;">​</a></h2><p>The same command reads the persisted index without touching it. Every mode prints plain lines meant for a terminal or <code>grep</code>, and works while an editor session holds the index open.</p><ul><li><code>clice index --stats [--top &lt;n&gt;]</code> prints what the index contains: the translation units and file shards, the byte split of the shard columns and of the global symbol table, how symbols distribute by reference-file count and name length, how file shards distribute by variant count, and the largest shards. <code>--variants</code> appends one tab-separated line per file shard with its variant count, for comparing two runs.</li><li><code>clice index --show-symbol &lt;name&gt;</code> prints what the index records about a symbol: its kind, name and flags, the parent chain that spells its qualified name, the file holding its canonical declaration, and per file how many definitions, declarations and references it has. The name is matched as displayed (<code>Box&lt;int&gt;</code>) or qualified (<code>ns::Box&lt;int&gt;</code>); <code>#&lt;hash&gt;</code> names a symbol by its identity, which is how file-local symbols are reached.</li><li><code>clice index --show-file &lt;path&gt;</code> prints a file&#39;s persisted rows: the content generation the rows were built from, every variant with the translation units that contributed it, the row counts by relation kind, and the file-local symbols whose identities live only in this file.</li><li><code>clice index --show-tu &lt;path&gt;</code> prints a translation unit&#39;s manifest: when it was indexed, the files it contributed rows to, and its include tree.</li></ul>',9)])])}const m=t(a,[["render",s]]);export{f as __pageData,m as default};
